\begin{algorithm}
\algname{Algorithm}
\caption{$\KeyGen(1^\secpar)$}
\begin{algorithmic}
\State $p, q \getsr$ random $\secpar$-bit primes; $n \gets pq$
\State $\lambda \gets \mathrm{lcm}(p-1, q-1)$
\Return $(\sk, \pk) \gets (\lambda, n)$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\Enc(\pk, m)$}
\begin{algorithmic}
\State $r \getsr \ZZ_n^*$
\Comment{$m \in \ZZ_n$; $g = 1+n$ has order $n$ in $\ZZ_{n^2}^*$}
\Return $c \gets (1+n)^m \cdot r^n \bmod n^2$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\Dec(\sk, c)$}
\begin{algorithmic}
\State $L(u) := (u-1)/n$
\Return $m \gets L(c^{\lambda} \bmod n^2) \cdot \lambda^{-1} \bmod n$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\Gen(1^\secpar)$}
\begin{algorithmic}
\State $(\GG, g, p) \gets \GrGen(1^\secpar)$; $h \getsr \GG$
\Return $\pp \gets (\GG, g, p, h)$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\Com(\pp, m; r)$}
\begin{algorithmic}
\Return $(c, d) \gets (g^m h^r, (m, r))$
\Comment{$m \in \ZZ_p$, $r \in \ZZ_p$}
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\Open(\pp, c, (m, r))$}
\begin{algorithmic}
\If{$c = g^m h^r$}
\Return $m$
\EndIf
\Return $\bot$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\KeyGen(1^\secpar)$}
\begin{algorithmic}
\State $(\GG, g, p) \gets \GrGen(1^\secpar)$
\State $x \getsr [p]$; $y \gets g^x$
\Return $(\sk, \pk) \gets ((\GG, g, p, x), (\GG, g, p, y))$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\Enc(\pk, m)$}
\begin{algorithmic}
\State $r \getsr [p]$
\Comment{$m \in \GG$}
\Return $c \gets (g^r, m \cdot y^r)$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\Dec(\sk, (c_1, c_2))$}
\begin{algorithmic}
\Return $m \gets c_2 \cdot c_1^{-x}$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\KeyGen(1^\secpar)$}
\begin{algorithmic}
\State $(\GG, g, p) \gets \GrGen(1^\secpar)$
\State $(a_0, a_1, \ldots, a_n) \getsr [p]^{n+1}$
\Return $k \gets (\GG, g, p, a_0, \ldots, a_n)$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\Eval(k, x)$}
\begin{algorithmic}
\Comment{$x \in \bits^n$; $\calD = \bits^n$, $\calR = \GG$}
\Return $g^{a_0 \prod_{i : x_i = 1} a_i}$
\end{algorithmic}
\end{algorithm}
